def check_scope_hierarchy(granted_scopes: List[str], required_scope: str) -> bool:
    """
    Checks if a required scope is satisfied by any granted scope, considering hierarchy.
    A required scope (e.g., 'items') is satisfied by a granted scope (e.g., 'items:read')
    if the granted scope starts with the required scope followed by a colon.
    """
    prefix = f"{required_scope}:"
    for granted_scope in granted_scopes:
        if granted_scope == required_scope or granted_scope.startswith(prefix):
            return True
    return False

